// Clean null/undefined values from fields
for (const route of routes) {
    for (const [key, val] of Object.entries(route.fields)) {
        if (val === undefined || val === null) delete route.fields[key];
    }
}

if (routes.length === 0) {
    node.status({ fill: 'yellow', shape: 'ring', text: 'no routes matched' });
} else {
    node.status({ fill: 'blue', shape: 'dot', text: routes.length + ' route(s)' });
}

// Build response and route messages
const responseMsg = {
    payload: { message: routes.length > 0 ? 'accepted' : 'no matching routes', routes: routes.length },
    statusCode: 200,
    res: msg.res,
};

const routeMsgs = routes.map(route => ({ tulipRoute: route }));

return [responseMsg, routeMsgs];

const instanceUrl = (env.get('TULIP_INSTANCE_URL') || '').replace(/\/$/, '');
const apiKey = env.get('TULIP_API_KEY');
const apiSecret = env.get('TULIP_API_SECRET');
const workspace = env.get('TULIP_WORKSPACE');
const ws = workspace ? '/w/' + workspace : '';

if (!instanceUrl || !apiKey || !apiSecret) {
    node.error('Missing required env vars: TULIP_INSTANCE_URL, TULIP_API_KEY, TULIP_API_SECRET');
    node.status({ fill: 'red', shape: 'ring', text: 'missing env vars' });
    return null;
}

const route = msg.tulipRoute;
const base = instanceUrl + '/api/v3' + ws + '/tables/' + route.tableId;
const auth = 'Basic ' + Buffer.from(apiKey + ':' + apiSecret).toString('base64');

msg._tulipAuth = auth;
msg._tulipBase = base;

if (route.mode === 'insert') {
    // Direct POST
    msg.url = base + '/records';
    msg.method = 'POST';
    msg.headers = { 'Authorization': auth, 'Content-Type': 'application/json' };
    msg.payload = Object.assign({ id: route.recordId }, route.fields);
    msg._tulipPhase = 'done';
    msg._tulipAction = 'created';
    node.status({ fill: 'blue', shape: 'dot', text: 'POST ' + route.recordId });
} else {
    // Upsert: start with GET to check existence
    msg.url = base + '/records/' + encodeURIComponent(route.recordId);
    msg.method = 'GET';
    msg.headers = { 'Authorization': auth, 'Content-Type': 'application/json' };
    msg._tulipPhase = 'get';
    node.status({ fill: 'blue', shape: 'dot', text: 'GET ' + route.recordId });
}

return msg;

const route = msg.tulipRoute;
const status = msg.statusCode;
const phase = msg._tulipPhase;

// Output 1: next HTTP request (upsert continuation)
// Output 2: final result summary (for debug / downstream use)

if (phase === 'done') {
    const ok = status >= 200 && status < 300;
    const summary = {
        payload: {
            route: route.name,
            recordId: route.recordId,
            action: msg._tulipAction,
            statusCode: status,
            result: ok ? 'success' : 'failed',
        },
    };
    if (ok) {
        node.log('Tulip ' + msg._tulipAction + ': ' + route.name + ' / ' + route.recordId);
        node.status({ fill: 'green', shape: 'dot', text: msg._tulipAction + ' ' + route.recordId });
    } else {
        node.error('Tulip ' + msg._tulipAction + ' failed (' + status + '): ' + route.name + ' / ' + route.recordId, msg);
        node.status({ fill: 'red', shape: 'dot', text: 'failed ' + status });
        summary.payload.error = msg.payload;
    }
    return [null, summary];
}

// Phase was 'get' — decide whether to update or create
if (phase === 'get') {
    if (status === 200) {
        // Record exists — PUT (Tulip Tables API uses PUT, not PATCH)
        msg.url = msg._tulipBase + '/records/' + encodeURIComponent(route.recordId);
        msg.method = 'PUT';
        msg.headers = { 'Authorization': msg._tulipAuth, 'Content-Type': 'application/json' };
        msg.payload = route.fields;
        msg._tulipPhase = 'done';
        msg._tulipAction = 'updated';
        node.status({ fill: 'blue', shape: 'dot', text: 'PUT ' + route.recordId });
        return [msg, null];
    }
    if (status === 404) {
        // Record does not exist — POST
        msg.url = msg._tulipBase + '/records';
        msg.method = 'POST';
        msg.headers = { 'Authorization': msg._tulipAuth, 'Content-Type': 'application/json' };
        msg.payload = Object.assign({ id: route.recordId }, route.fields);
        msg._tulipPhase = 'done';
        msg._tulipAction = 'created';
        node.status({ fill: 'blue', shape: 'dot', text: 'POST ' + route.recordId });
        return [msg, null];
    }
    // Unexpected status on the existence check
    node.error('Tulip GET failed (' + status + '): ' + route.name + ' / ' + route.recordId, msg);
    node.status({ fill: 'red', shape: 'dot', text: 'GET failed ' + status });
    return [null, {
        payload: {
            route: route.name,
            recordId: route.recordId,
            action: 'get',
            statusCode: status,
            result: 'failed',
            error: msg.payload,
        },
    }];
}

return [null, null];
